#include <iostream>

class Count {
public:
    int count;
    Count() : count(0) {}
    explicit Count(int c) : count(c) {}
};

void incrementByVal(Count c, int times) {
    c.count++;
    times++;
}

void incrementByRef(Count& c, int& times) {
    c.count++;
    times++;
}

void inspect(const Count& c, int times) {
    std::cout << "myCount.count is " << c.count << " times is " << times << "\n";
}

int main() {
    Count myCount;
    int times = 0;

    for (int i = 0; i < 100; ++i) {
        incrementByVal(myCount, times);
    }
    inspect(myCount, times);

    for (int i = 0; i < 5; ++i) {
        incrementByRef(myCount, times);
    }
    inspect(myCount, times);

    return 0;
}

#include <iostream>
#include <iomanip>

class Circle {
private:
    double radius;
public:
    Circle() : radius(1.0) {}
    explicit Circle(double r) : radius(r >= 0 ? r : 0) {}
    double getRadius() const { return radius; }
    void setRadius(double r) { radius = (r >= 0 ? r : 0); }
    double getArea() const { return radius * radius * 3.14159; }
};

double sum(const Circle circleArray[], int size) {
    double total = 0;
    for (int i = 0; i < size; ++i) {
        total += circleArray[i].getArea();
    }
    return total;
}

void printCircleArray(const Circle circleArray[], int size) {
    std::cout << std::left << std::setw(10) << "Radius" << std::setw(12) << "Area" << "\n";
    for (int i = 0; i < size; ++i) {
        std::cout << std::left << std::setw(10) << circleArray[i].getRadius()
                  << std::setw(12) << circleArray[i].getArea() << "\n";
    }
    std::cout << "----------------------\n";
    std::cout << "Total Area: " << sum(circleArray, size) << "\n";
}

int main() {
    const int SIZE = 3;
    Circle circleArray[SIZE];
    for (int i = 0; i < SIZE; ++i) {
        circleArray[i].setRadius(i + 1);
    }
    printCircleArray(circleArray, SIZE);
    return 0;
}

#include <iostream>

class Circle {
private:
    double radius;
    static inline int numberOfObjects = 0; // C++17 inline static variable

public:
    Circle() : radius(1.0) {
        numberOfObjects++;
    }

    explicit Circle(double r) : radius(r >= 0 ? r : 0) {
        numberOfObjects++;
    }

    double getRadius() const { return radius; }
    void setRadius(double r) { radius = (r >= 0 ? r : 0); }
    double getArea() const { return radius * radius * 3.14159; }

    static int getNumberOfObjects() {
        return numberOfObjects;
    }
};

int main() {
    std::cout << "Initial count: " << Circle::getNumberOfObjects() << "\n";

    Circle c1;
    std::cout << "After c1, count: " << Circle::getNumberOfObjects() << "\n";

    Circle c2(5.0);
    std::cout << "After c2, count: " << c2.getNumberOfObjects() << "\n";

    std::cout << "c1 radius: " << c1.getRadius() << ", c2 radius: " << c2.getRadius() << "\n";
    return 0;
}
